import { SegmentedControl } from '@kerfjs/ui/segmented-control';

type WorkspaceView = 'board' | 'list' | 'timeline';

export function mountWorkspaceViewSwitcher(target: HTMLElement, app: { view: WorkspaceView; dispatch(action: { type: 'workspace.view.changed'; view: WorkspaceView }): void }) {
  return SegmentedControl({
    target,
    label: 'Workspace view',
    value: app.view,
    options: [
      { value: 'board', label: 'Board' },
      { value: 'list', label: 'List' },
      { value: 'timeline', label: 'Timeline' }
    ],
    onChange: (view: WorkspaceView) => app.dispatch({ type: 'workspace.view.changed', view })
  });
}
